// Creates one meaningful commit per stage (and what-if branches) with the GitHub git data API,
// then reports back to the Go backend. The token is only in this execution's memory
// (the workflow does not save execution data).
const p = $input.first().json.body;
const gh = async (method, path, body) => this.helpers.httpRequest({
  method, url: 'https://api.github.com' + path, body, json: true,
  headers: { Authorization: 'Bearer ' + p.github_token, Accept: 'application/vnd.github+json',
             'X-GitHub-Api-Version': '2022-11-28', 'User-Agent': 'research-lab-n8n' },
});
const refSha = async (branch) => (await gh('GET', `/repos/${p.repo}/git/ref/heads/${encodeURIComponent(branch)}`)).object.sha;
const callback = async (body) => this.helpers.httpRequest({
  method: 'POST', url: p.callback_url, json: true, body: { push_id: p.push_id, ...body },
  headers: { 'X-Internal-Token': p.callback_token },
});

const results = [];
try {
  try { await refSha(p.base_branch); }
  catch (e) { await gh('PUT', `/repos/${p.repo}/contents/.gitkeep`, { message: 'Initialize repository', content: '', branch: p.base_branch }); }
  for (const c of p.commits) {
    const branch = c.branch || p.base_branch;
    let head, created = false;
    try { head = await refSha(branch); }
    catch (e) { head = await refSha(c.from_branch || p.base_branch); created = true; }
    const parent = await gh('GET', `/repos/${p.repo}/git/commits/${head}`);
    const tree = [];
    for (const f of c.files) {
      const blob = await gh('POST', `/repos/${p.repo}/git/blobs`, { content: f.content_base64, encoding: 'base64' });
      tree.push({ path: f.path, mode: '100644', type: 'blob', sha: blob.sha });
    }
    const t = await gh('POST', `/repos/${p.repo}/git/trees`, { base_tree: parent.tree.sha, tree });
    const commit = await gh('POST', `/repos/${p.repo}/git/commits`, { message: c.message, tree: t.sha, parents: [head] });
    if (created) await gh('POST', `/repos/${p.repo}/git/refs`, { ref: 'refs/heads/' + branch, sha: commit.sha });
    else await gh('PATCH', `/repos/${p.repo}/git/refs/heads/${encodeURIComponent(branch)}`, { sha: commit.sha, force: false });
    results.push({ branch, sha: commit.sha, message: c.message, url: `https://github.com/${p.repo}/commit/${commit.sha}` });
  }
  await callback({ status: 'done', repo_url: 'https://github.com/' + p.repo, commits: results });
} catch (e) {
  await callback({ status: 'failed', error: String(e.message || e).slice(0, 500), commits: results });
}
return [{ json: { ok: true, commits: results.length } }];
